//! The atmosphere study (#15): its published table matches the code, and every value agrees with
//! the 1976 standard's tables to four significant figures.

use mjk_env::reference::USSA_1976;
use mjk_sim::validation::atmosphere::{
    FOUR_FIGURES, atmosphere_study, fourth_figure_gap, markdown, passed,
};

/// The table the book includes, generated by `mjk validate atmosphere`.
const PUBLISHED: &str = include_str!("../../../docs/src/validation/atmosphere.md");

#[test]
fn the_published_table_matches_the_code() {
    let rows = atmosphere_study().expect("every published altitude is in range");
    assert_eq!(
        markdown(&rows),
        PUBLISHED,
        "regenerate with: cargo run -p mjk-cli -- validate atmosphere > docs/src/validation/atmosphere.md"
    );
}

#[test]
fn every_value_agrees_to_four_significant_figures() {
    let rows = atmosphere_study().expect("every published altitude is in range");
    assert_eq!(rows.len(), USSA_1976.len());
    for row in &rows {
        assert!(row.worst_gap <= 0.5, "{row:?}");
        assert!((row.model.temperature_k - row.table.temperature_k).abs() < 1e-3);
    }
    // The largest gap anywhere is a tenth of a unit, at 11 km.
    let worst = rows.iter().map(|row| row.worst_gap).fold(0.0, f64::max);
    assert!(worst < 0.15, "{worst}");
}

#[test]
fn a_gap_is_measured_in_units_of_the_fourth_figure() {
    assert!((fourth_figure_gap(22_700.0, 22_699.0) - 0.1).abs() < 1e-9);
    assert!((fourth_figure_gap(1.2256, 1.2250) - 0.6).abs() < 1e-9);
    assert!((fourth_figure_gap(1.7900e-5, 1.7894e-5) - 0.6).abs() < 1e-6);
}

#[test]
fn the_study_passes_when_every_altitude_agrees_to_four_figures() {
    let mut rows = atmosphere_study().expect("every published altitude is in range");
    assert!(passed(&rows));
    assert!((FOUR_FIGURES - 0.5).abs() < f64::EPSILON);
    rows[2].worst_gap = FOUR_FIGURES;
    assert!(
        passed(&rows),
        "half a unit still rounds to the same fourth figure"
    );
    rows[2].worst_gap = 0.51;
    assert!(!passed(&rows));
    assert!(passed(&[]), "nothing to disagree with");
}
